const i={title:"TripReel - App di Animazione Viaggi Gratuita: Trasforma le Foto in Video Bellissimi",description:"Crea video di viaggio mozzafiato con mappe animate e rotte di volo. App di animazione viaggi gratuita con mappatura rotta globo 3D. Trasforma le tue foto in video di viaggio belli automaticamente. Privacy prima, funziona offline.",keywords:"app di animazione viaggi, app di animazione mappa viaggi, app di animazione rotta viaggi, app di animazione volo, creatore video viaggi, video viaggio automatico, mappa viaggio animata, animazione rotta volo, animazione viaggio, animazione globo, video riepilogo viaggio, foto a video, highlights viaggio, app viaggio gratuita, creatore video offline, app viaggio privata, video rullino"},e={logoAlt:"Logo TripReel",appName:"TripReel",howItWorks:"Come funziona",video:"Video",features:"Funzionalità",theApp:"L'app"},a={badge:"Trasforma le foto in storie di viaggio",title1:"Il tuo rullino,",title2:"pienamente sfruttato",description:"TripReel crea automaticamente splendidi video di viaggio dalle posizioni delle tue foto. Guarda i tuoi viaggi prendere vita con straordinarie mappe di percorso animate e rotte aeree su un globo 3D, mentre i tuoi dati rimangono privati e sicuri.",secure:"100% sicuro",worksOffline:"Funziona offline",globeAlt:"Animazione del globo TripReel"},o={title:"Come funziona",subtitle:"Tre semplici passaggi per creare il tuo video di viaggio perfetto",step1:{title:"Consenti accesso alle foto",description:"Concedi a TripReel l'accesso alla tua libreria foto. L'app legge solo i metadati di posizione, nient'altro."},step2:{title:"Rilevamento automatico dei viaggi",description:"TripReel analizza i metadati di posizione e trova intelligentemente i tuoi viaggi in base a date e luoghi."},step3:{title:"Genera il tuo video",description:"Guarda il tuo viaggio svolgersi su una splendida animazione del globo, pronta da condividere sui social media."}},t={title:"Vedi la magia in azione",subtitle:"Scopri come TripReel trasforma la tua libreria foto in straordinari video di viaggio",caption:"Ecco come può apparire il tuo video di viaggio finale"},n={title:"Tutto ciò di cui hai bisogno",subtitle:"Funzionalità potenti progettate per i viaggiatori moderni",twoTap:{title:"Video di viaggio con due tocchi",description:"Crea straordinari video di viaggio dalla tua libreria foto con soli due tocchi. Nessuna modifica necessaria."},smartTrip:{title:"Rilevamento intelligente dei viaggi",description:"Trova e raggruppa automaticamente i tuoi viaggi analizzando date e metadati di posizione dalle tue foto."},globe:{title:"Splendida animazione del globo",description:"Guarda il tuo viaggio prendere vita con uno straordinario globo 3D che mostra i tuoi percorsi di viaggio animati e le rotte aeree in tutto il mondo."},privacy:{title:"Privacy al primo posto",description:"Tutto viene elaborato sul tuo dispositivo. Le tue foto non escono mai dal tuo telefono. Funziona in modalità aereo."},customStyles:{title:"Stili personalizzati",description:"Scegli tra più stili di globo e personalizzazioni per adattarsi alla tua estetica e rendere ogni video unico."},manualControl:{title:"Controllo manuale",description:"Puoi aggiungere manualmente viaggi completamente nuovi se i servizi di localizzazione non erano abilitati sul tuo dispositivo."}},r={title:"Idee creative per i video",subtitle:"Lasciati ispirare da ciò che puoi creare con TripReel. Dai rapidi weekend alle avventure di un anno, crea straordinari video di viaggio per ogni percorso.",description:"Che tu stia creando un'animazione di mappa di viaggio, documentando una rotta aerea o realizzando un riepilogo annuale dei viaggi, TripReel rende facile trasformare i tuoi ricordi in video condivisibili.",ideas:{yearRecap:{title:"Riepilogo viaggi 2025",description:"Crea automaticamente il tuo video riepilogo annuale dei viaggi 2025"},europeRoadTrip:{title:"Viaggio in auto in Europa",description:"Mostra la tua avventura europea con mappe di percorso animate"},southeastAsia:{title:"Viaggio nel Sud-Est Asiatico",description:"Visualizza il tuo percorso zaino in spalla attraverso più paesi"},japanRail:{title:"Viaggio in treno in Giappone",description:"Crea video di mappe dei tuoi percorsi in treno attraverso il Giappone"},crossCountry:{title:"Da costa a costa negli USA",description:"Trasforma il tuo viaggio americano in un epico video di percorso"},islandHopping:{title:"Tour tra le isole",description:"Mostra i tuoi viaggi da isola a isola con straordinarie animazioni 3D"},worldTour:{title:"Montaggio giro del mondo",description:"Più viaggi in un unico straordinario video di viaggio globale"},travelPlans:{title:"Piani di viaggio 2026",description:"Visualizza e pianifica le tue emozionanti avventure di viaggio per il 2026"},lifetimeTravel:{title:"Storia di viaggio di una vita",description:"Crea un video che mostra tutti i tuoi viaggi di una vita"},regionalExplorer:{title:"Esploratore regionale",description:"Traccia le tue avventure attraverso stati, province e regioni"},festivalCircuit:{title:"Circuito dei festival",description:"Traccia il tuo viaggio tra festival musicali ed eventi"},bikeRoutes:{title:"Le mie fughe in città",description:"Mostra tutte le tue fughe urbane"}}},l={title:"L'app",subtitle:"Disponibile ora sull'App Store",alt1:"Video di viaggio automatici - Crea video straordinari in secondi",alt2:"Rilevamento posizione foto - Usa i metadati delle tue foto",alt3:"Rilevamento viaggi - Raggruppa automaticamente i tuoi viaggi",alt4:"Splendidi video del globo - Animazione del globo del tuo viaggio",alt5:"Stili personalizzati - Personalizza i tuoi video di viaggio"},s={comingSoon:"Prossimamente",androidTitle:"App Android in arrivo!",androidMessage:'La versione Android non è ancora disponibile ma lo sarà presto. Scrivimi a <a href="mailto:marian@qod.ee?subject=TripReel%20Android%20App" class="text-sky-600 dark:text-sky-400 hover:text-sky-700 dark:hover:text-sky-300 font-semibold transition-colors">marian@qod.ee</a> e ti avviserò quando sarà pronta!',gotIt:"Capito!"},d={title:"Domande frequenti",subtitle:"Tutto quello che devi sapere su TripReel",q1:{question:"Posso davvero usare l'app completamente in modalità aereo?",answer:"Sì! Per gli utenti premium, l'app può essere utilizzata completamente offline in modalità aereo senza limitazioni. Per gli utenti non premium, alcune funzionalità sono supportate da pubblicità che potrebbero richiedere l'abilitazione temporanea di Internet, ma per gli utenti premium non ci sono annunci e l'app può essere utilizzata completamente in modalità aereo."},q2:{question:"Ho fatto l'upgrade a Premium, come posso rimuovere la filigrana?",answer:"Molte persone chiedono quale app è stata utilizzata per creare questi video, quindi dopo l'upgrade a premium, hai l'opzione di aggiungere una versione più piccola della filigrana (solo con il nome dell'app) o rimuoverla completamente se lo desideri."},q3:{question:"I dati delle mie foto sono sicuri e privati?",answer:"Assolutamente! TripReel legge solo i metadati di posizione dalle tue foto - non accediamo mai, archiviamo o trasmettiamo il contenuto effettivo delle foto. Tutta l'elaborazione avviene localmente sul tuo dispositivo e nessun dato lascia mai il tuo telefono. Puoi verificarlo utilizzando l'app in modalità aereo - funziona perfettamente offline!"},q4:{question:"E se le mie foto non hanno dati di posizione?",answer:"Nessun problema! Se i servizi di localizzazione non erano abilitati quando hai scattato le foto, puoi creare manualmente viaggi e aggiungere posizioni tu stesso. L'app ti dà il controllo completo per personalizzare la tua timeline di viaggio."},q5:{question:"Come rileva l'app i miei viaggi automaticamente?",answer:"TripReel analizza i metadati di posizione e i timestamp dalle tue foto per identificare intelligentemente quando e dove hai viaggiato. Raggruppa posizioni e date vicine per rilevare automaticamente i tuoi viaggi senza alcun lavoro manuale."},q6:{question:"Posso personalizzare l'aspetto dei miei video?",answer:"Sì! Puoi scegliere tra più stili di globo e personalizzare vari aspetti dei tuoi video di viaggio animati per adattarli alla tua estetica personale. Gli utenti premium ottengono l'accesso a stili di animazione del percorso aggiuntivi, temi di mappe e opzioni di rotte aeree."},q7:{question:"Devo creare un account?",answer:"Nessun account richiesto! TripReel funziona immediatamente dopo il download. Non c'è registrazione, nessun login e nessuna informazione personale necessaria. Scarica semplicemente l'app e inizia subito a creare i tuoi video di viaggio."},q8:{question:"Perché manca una posizione dal mio viaggio?",answer:"L'app può funzionare solo con i dati disponibili, quindi prima di tutto hai bisogno di almeno un paio di foto in quella posizione. In secondo luogo, devi assicurarti di aver abilitato i dati di posizione quando eri lì. In terzo luogo, a volte una scarsa ricezione GPS può causare dati di posizione errati. Se hai escluso tutto questo e la tua posizione non viene ancora visualizzata, puoi aggiungere manualmente quella posizione da Panoramica viaggi > pulsante Modifica. Ti preghiamo di utilizzare anche Contatto per segnalare il problema."},q9:{question:"Dove posso condividere il mio fantastico video?",answer:"Naturalmente, puoi anche condividerlo su tutte le piattaforme social. Per adattarsi meglio alla piattaforma, l'app consente diverse proporzioni per i tuoi video."},q10:{question:"Dove posso segnalare un bug?",answer:"Contattami direttamente a marian@qod.ee, spiegando brevemente qual è il problema."}},p={title:"Supporto via email",description:"Se hai feedback o riscontri problemi, non esitare a contattarmi direttamente a questo indirizzo email e leggerò e gestirò personalmente la tua richiesta il più rapidamente possibile. Grazie per aver utilizzato l'app!",close:"Chiudi"},u={default:{title:"🍪 Cookie",message:"Utilizziamo i cookie sul sito TripReel per migliorare la tua esperienza. Nessun dato personale raccolto.",accept:"Accetta",decline:"Rifiuta",details:"Dettagli"},theme:{title:"🍪 Cookie",message:"🌙 Per salvare la tua preferenza del tema, devi accettare i cookie essenziali sul sito TripReel. Senza di essi, la tua scelta del tema non può essere salvata.",accept:"Accetta",decline:"Rifiuta",details:"Dettagli"}},c={privacy:"Informativa sulla privacy dell'app",cookies:"Informativa sui cookie del sito",contact:"Contatto",cookiePreferences:"Preferenze cookie",madeWith:"Creato con",forTravelers:"per viaggiatori in tutto il mondo",copyright:"© {{year}} TripReel."},g={title:"Pronto a condividere il tuo viaggio?",description:"Scarica TripReel oggi e trasforma il tuo rullino in splendidi video di viaggio con mappe e percorsi animati. Le tue avventure meritano di essere celebrate.",features:"Download gratuito • Veloce e conveniente • Privacy garantita"},m={meta:i,header:e,hero:a,howItWorks:o,videoSection:t,features:n,videoIdeas:r,screenshots:l,appStore:s,faq:d,contact:p,cookieBanner:u,footer:c,cta:g};export{s as appStore,p as contact,u as cookieBanner,g as cta,m as default,d as faq,n as features,c as footer,e as header,a as hero,o as howItWorks,i as meta,l as screenshots,r as videoIdeas,t as videoSection};
